137	/**
138	 * The room's listing: private matches are found by `code` (Colyseus `filterBy`). It never holds the
139	 * creator's `createToken`, so a request carrying a token matches no listing.
140	 */
141	export interface MatchMetadata {
142	  code: string;
143	  custom: boolean;
144	  /** The match has left its lobby: admission refuses every join (§2: late arrivals wait for another match). */
145	  started?: boolean;
146	  /** A `filterBy` field that is never set: no listing holds a token, so no token-carrying request matches one. */
147	  createToken?: never;
148	}
149	
150	/** World updates go out at 20 Hz, the world simulation rate (§15). */
151	const PATCH_INTERVAL_MS = 1000 / 20;
152	
153	/** World ticks a second (§15). */
154	const WORLD_TICKS_PER_SECOND = STEPS_PER_SECOND / WORLD_STEP_INTERVAL;
155	
156	/**
157	 * World ticks a settled duel's lobby stays in its fighters' views, so both read the result before their clients return
158	 * to the sea (2 s). The winner's protection and the loser's respawn already run meanwhile.
159	 */
160	export const DUEL_RESULT_TICKS = 40;
161	
162	/**
163	 * Colyseus' reconnection window (§12): only an outer bound that keeps the socket's seat open. The world tick decides
164	 * everything else (the 60 s seat reservation, the 10 s duel absence); if this window closes first, it is a quit.
165	 */
166	export const RECONNECTION_OUTER_BOUND_SECONDS = 70;
167	
168	/** The key suffix of a grapple's blanked twin, the entry for viewers who see the attacker but not the defender (§16). */
169	export const BLANK_GRAPPLE_SUFFIX = "~";
170	
171	/**
172	 * A match's timings and test-only settings. Production uses `DEFAULT_MATCH_TUNING`; tests shorten the timings through
173	 * `startGameServer({ matchTuning })` (never read by the production entry), and assert in world ticks.
174	 */
175	export interface MatchTuning {
176	  /** The ledger's rules (§4, §11, §12): collection and claim holds, the theft window, the seat reservation, gold. */
177	  readonly objectives: ObjectiveRules;
178	  /** The encounter rules (§6): windups, the countdown and ready check, protections, the respawn delay. */
179	  readonly encounters: EncounterRules;
180	  /** §12: world ticks a fighter may be away from an unfinished duel before forfeiting it (10 s). */
181	  readonly duelAbsenceTicks: number;
182	  /** Colyseus' reconnection window, the outer bound (70 s). */
183	  readonly reconnectionSeconds: number;
184	  /** §2's lobby and ready countdown (`readyTicks`); the departure is the encounter rules' spawn protection. */
185	  readonly match: MatchRules;
186	  /** §5's claim channel and circle, and §2's deadline: the timer's duration is this `deadlineTicks`. */
187	  readonly claim: ClaimRules;
188	  /** §2's minute-20 and minute-28 reveals. */
189	  readonly intel: IntelRules;
190	  /** Test-only: deal the sources in this layout (types per island) instead of the private shuffle. */
191	  readonly sourceLayout: readonly (readonly string[])[] | undefined;
192	  /**
193	   * The match's one private master secret (§3, §16), from which every system's seed is derived (`deriveSeed`):
194	   * production draws it from `node:crypto` (`drawMasterSecret`); tests inject their own to show what follows it.
195	   */
196	  readonly masterSecret: () => Uint8Array;
197	  /** Test-only: the final-socket secret instead of the one derived from the master secret, so a test knows the island. */
198	  readonly finalSocketSecret: number | undefined;
199	  /** Test-only: the room's `injectFault` and `pauseAfterTick` hooks work (off by default; they throw otherwise). */
200	  readonly testHooks: boolean;
201	  /** Check `checkLedger` and the room's own invariant after every world tick (development and tests). */
202	  readonly checkInvariants: boolean;
203	}
204	
205	export const DEFAULT_MATCH_TUNING: MatchTuning = {
206	  objectives: objectiveRules,
207	  encounters: encounterRules,
208	  duelAbsenceTicks: DUEL_RECONNECT_SECONDS * WORLD_TICKS_PER_SECOND,
209	  reconnectionSeconds: RECONNECTION_OUTER_BOUND_SECONDS,
210	  match: defaultMatchRules,
211	  claim: defaultClaimRules,
212	  intel: defaultIntelRules,
213	  sourceLayout: undefined,
214	  masterSecret: drawMasterSecret,
215	  finalSocketSecret: undefined,
216	  testHooks: false,
217	  checkInvariants: true,
218	};
219	
220	/** A finished match as the process recorded it (§16's result: the match, its end reason, winner and summaries). */
221	export interface MatchOutcome {
222	  readonly code: string;
223	  readonly results: MatchResults;
224	}
225	
226	/** Every match this process has finished, oldest first (the first release stores final outcomes only, §12). */
227	const outcomes: MatchOutcome[] = [];
228	
229	/** The outcomes this process recorded so far, for tests and diagnostics. */
230	export function recordedOutcomes(): readonly MatchOutcome[] {
231	  return outcomes;
232	}
233	
234	/** A duel at sea: the encounter rules' duel, its synced lobby and marker, and the duel machine the fighters play. */
235	interface SeaDuel {
236	  /** The encounter rules' duel id, also the ledger's. */
237	  readonly id: string;
238	  /** The opaque key of its lobby and marker in the synced state. */
239	  readonly key: string;
240	  /** Attacker (slot 0), then the grappled player (slot 1). */
241	  readonly players: readonly [string, string];
242	  readonly lobby: SeaDuelSchema;
243	  readonly machine: DuelMachine;
244	  /** The rules' ready check ended it (a forfeit or a cancellation), so no end report goes back to them. */
245	  endedByRules: boolean;
246	  /** The fight's end went to the rules (or they decided it themselves). */
247	  ended: boolean;
248	  /** The ledger's settlement went to the rules. */
249	  settled: boolean;
250	  /** The world tick after which the lobby leaves the fighters' views, once settled. */
251	  removeAfterTick: number | undefined;
252	}
253	
254	/** A player whose connection dropped (§12): their seat's outer bound, and since when they are away from a duel. */
255	interface Away {
256	  readonly reconnection: Deferred<Client> | undefined;
257	  /** The world tick they dropped out of an unfinished duel; undefined outside one. */
258	  duelAbsentSince: number | undefined;
259	}
260	
261	/** What a player last saw of their own holds and duels, for their HUD. */
262	interface Notices {
263	  channelResult: string;
264	  channelResultAt: number;
265	  settledRole: string;
266	  stolen: string;
267	  goldChange: number;
268	  settledAt: number;
269	  settledChoice: string;
270	  choiceDeadline: number;
271	  /** §5: why this player's last claim channel reset, and on which world tick. */
272	  claimInterrupt: string;
273	  claimInterruptAt: number;
274	}
275	
276	/** A player's final-island route (§5), as the reveals gave it: known once, inactive while the set is broken. */
277	interface Route {
278	  active: boolean;
279	  readonly x: number;
280	  readonly y: number;
281	}
282	
283	/** What tests and diagnostics read about a duel at sea. */
284	export interface SeaDuelDiagnostics extends DuelDiagnostics {
285	  readonly id: string;
286	  readonly outcome: DuelOutcome | undefined;
287	  readonly players: readonly [string, string];
288	  readonly seed: number;
289	  readonly inputLog: ReturnType<DuelAuthority["inputLog"]>;
290	}
291	
292	/** Checks a create or join request for a match before matchmaking places it (see `authorizePrivateEntry`). */
293	export async function authorizeEntry(options: unknown): Promise<true> {
294	  return authorizePrivateEntry(options, MATCH_ADMISSION);
295	}
296	
297	/** A match's admission: the `match` listing, the match option schemas and the match refusal messages. */
298	const MATCH_ADMISSION: AdmissionRules = {
299	  roomName: MATCH_ROOM,
300	  createSchema: createMatchOptionsSchema,
301	  joinSchema: joinMatchOptionsSchema,
302	  noSuchMessage: NO_SUCH_MATCH_MESSAGE,
303	  codeRequiredMessage: MATCH_CODE_REQUIRED_MESSAGE,
304	  fullMessage: matchFullMessage,
305	  startedMessage: MATCH_STARTED_MESSAGE,
306	};
307	
308	/** Who holds a rubbing at a location: its owner, or the player a duel reserves it for; nobody at a source or a cache. */
309	const holderOf = (location: RubbingLocation): string | undefined => (location.kind === "player" || location.kind === "duel" ? location.playerId : undefined);
310	
311	/** An intel message body as the reveal the room delivers, or undefined for the kinds it does not deliver yet. */
312	function revealOf(body: IntelMessageBody): RevealMessage | undefined {
313	  switch (body.kind) {
314	    case "final-sector":
315	      return { kind: body.kind, tick: body.tick, sector: body.sector, name: body.name };
316	    case "final-route":
317	      return { kind: body.kind, tick: body.tick, x: body.x, y: body.y, restored: body.restored };
318	    case "final-route-inactive":
319	      return { kind: body.kind, tick: body.tick };
320	    case "sector-reveal":
321	      return { kind: body.kind, tick: body.tick, sources: body.sources.map(({ sector, name }) => ({ sector, name })), caches: body.caches.map(({ sector, name }) => ({ sector, name })) };
322	    case "carrier-report":
323	      return { kind: body.kind, tick: body.tick, seenTick: body.seenTick, carriers: body.carriers.map(({ sector, name, type }) => ({ sector, name, type })) };
324	    default:
325	      // Rumors, sightings and the journal are `intel-online`'s.
326	      return undefined;
327	  }
328	}
329	
330	const sameTarget = (channel: LedgerChannel | null, target: InteractTarget): boolean =>
331	  channel !== null &&
332	  (target.kind === "collect"
333	    ? channel.kind === "collect" && channel.sourceId === target.sourceId
334	    : channel.kind === "claim" && channel.cacheId === target.cacheId && channel.rubbingId === target.rubbingId);
335	
336	/**
337	 * One private match (§14): the only writer of its state. It runs the shared simulation on a 60 Hz fixed step,
338	 * applies validated client intent, and mirrors the simulation into the synced schema after every world step.
339	 *
340	 * The match flow (§2, §5): the match module (`stepMatch`) runs the lobby, the host's start, the ready countdown and
341	 * control start, then the end and the results; ships take input only between control start and the end. From control
342	 * start each world tick runs §5's order: the encounters (reservations first), the ledger's holds, the claim channel
343	 * (`stepClaim`), the flow (with the tick's accomplishments and the claim's end), then the reveals (`stepIntel`, whose
344	 * reveal messages go to exactly their recipients). A world tick that throws aborts the match (§12). Every system's
345	 * seed is derived from one private master secret per match (`deriveSeed`), never from the match code.
346	 *
347	 * Encounters (§6): each world step the room builds the tick's snapshot for `stepEncounters` (every ship, whether its
348	 * player is connected, pressed the grapple, or has a loaded arena) and applies the events: a landed grapple stops both
349	 * ships and opens a duel at sea, a `DuelMachine` (the standalone duel room's own) whose fight starts when the rules
350	 * say so; its end goes back as a report; the returns and respawns move ships. Reserved and respawning ships get
351	 * neutral input.
352	 *
353	 * Rubbings (§4, §11, §12): the objective ledger is the only writer of rubbings and gold; the room calls its operations
354	 * and never moves either itself. Holding E moored at an island's dock collects its first eligible source, or else
355	 * claims a rubbing from a recovery cache at that dock. A reservation reserves the duel in the ledger; the fight's end
356	 * is reported to it; the room reports `settled` to the encounter rules only when the ledger has settled the duel (the
357	 * winner's theft choice, or the default at the deadline), and only then do the players return. The world tick drives
358	 * every §12 timer: a drop disconnects the player in the ledger at once (the ship stays, and can be grappled), a
359	 * fighter away from an unfinished duel forfeits it after `duelAbsenceTicks`, the seat expires at the ledger's
360	 * deadline into a cache at the respawn dock, and any other leave is a quit into a cache at the nearest dock by sea.
361	 * No path removes a ship while the ledger still counts its player; `checkInvariants` checks that and `checkLedger`
362	 * after every tick.
363	 *
364	 * Visibility (§16): every client has a Colyseus StateView. After each mirror the room puts into it the client's own
365	 * ship and every ship inside that ship's sight radius, and takes out the rest, so a ship out of sight is never encoded
366	 * into that client's patches. Ships in a duel or waiting to respawn are hidden from everyone else (a duel shows as a
367	 * marker). Grapples, markers and caches are filtered by the same sight rule (a grapple's target is blanked for a
368	 * viewer who cannot see it); a player's status (gold, rubbings, what their island and dock hold, their theft choice)
369	 * and duel go to that player only, and a duel's frames and probes are messages to its two fighters. A fighter or a
370	 * player waiting to respawn sees no other ship. Terrain is static content every client already has, so it is not
371	 * synced at all.
372	 */
373	export class MatchRoom extends Room<{ state: MatchStateSchema; metadata: MatchMetadata }> {
374	  override maxClients = privateMatch.maxPlayers;
375	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in InputGate. */
376	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
377	  override patchRate = PATCH_INTERVAL_MS;
378	  override state = new MatchStateSchema();
379	
380	  private readonly config = defaultSimulationConfig;
381	  private tuning: MatchTuning = DEFAULT_MATCH_TUNING;
382	  private encounterConfig: EncounterConfig = createEncounterConfig({ map: defaultSimulationConfig.map });
383	  private simulation: MatchState = createMatchState(0);
384	  private encounters: EncounterState = createEncounterState(this.encounterConfig);
385	  private ledger: LedgerState = createMatchLedger({ map: defaultSimulationConfig.map, seed: 0, rules: objectiveRules });
386	  private readonly gates = new Map<string, InputGate>();
387	  /** Duels at sea by encounter id, from the grapple until their lobby leaves the fighters' views. */
388	  private readonly seaDuels = new Map<string, SeaDuel>();
389	  private nextDuelKey = 1;
390	  /** Players whose connection dropped and who have not come back or left. */
391	  private readonly away = new Map<string, Away>();
392	  /** Players who started a collection, a cache claim or a treasure claim this tick: their protection ends on the next (§6). */
393	  private protectionEndedNext = new Map<string, "claim" | "collection">();
394	  private readonly notices = new Map<string, Notices>();
395	  /** Ledger duels whose settlement is already in the players' notices. */
396	  private readonly noticed = new Set<string>();
397	  /** Theft choices per session in the current second, for the rate cap. */
398	  private readonly choiceRate = new Map<string, { windowStart: number; count: number }>();
399	  /** Reports the rules refused (none are expected), for tests. */
400	  private refusedReports = 0;
401	  /** Ledger requests the room made that the ledger refused, by operation and reason, for tests. */
402	  private readonly refusals: string[] = [];
403	  /** Invariant violations found after a world tick (none are expected), for tests. */
404	  private readonly violations: string[] = [];
405	  /** The creator's one-time token; cleared once the creator's seat is taken. */
406	  private createToken: string | undefined;
407	
408	  /** The match's private master secret (§3, §16): every system's seed is derived from it, never from the code. */
409	  private secret: Uint8Array = new Uint8Array(32);
410	  /** Duels at sea opened so far, for their derived seeds. */
411	  private duelsOpened = 0;
412	  /** The final island (§3, §5): its socket and its claim point, the treasure circle's centre. Never synced to everyone. */
413	  private finalIsland: { readonly socket: number; readonly claimPoint: ClaimPoint } = { socket: 0, claimPoint: { x: 0, y: 0 } };
414	  /** §2's match flow: the lobby, the ready countdown, control start, the timer, the end and the results. */
415	  private flowConfig: FlowConfig = matchConfigFor(DEFAULT_MATCH_TUNING);
416	  private flow: FlowState = createFlowState(this.flowConfig);
417	  /** Reports for the flow's next step: joins, leaves and start requests between ticks, accomplishments on a tick. */
418	  private flowReports: FlowReport[] = [];
419	  /** §5's claim channel, from control start. */
420	  private claimConfig: ClaimConfig | undefined;
421	  private claim: ClaimState | undefined;
422	  /** §2 and §5's reveals, from control start. */
423	  private intelConfig: IntelConfig | undefined;
424	  private intel: IntelState | undefined;
425	  /** Each player's route to the final island, once revealed to them. */
426	  private readonly routes = new Map<string, Route>();
427	  /** The (player, island) pairs already reported as visited, and each player's last reported gold. */
428	  private readonly visited = new Set<string>();
429	  private readonly reportedGold = new Map<string, number>();
430	  /** Start requests per session in the current second, for the rate cap. */
431	  private readonly startRate = new Map<string, { windowStart: number; count: number }>();
432	  /** Where each rubbing was at the last world tick, for the results' accomplishments. */
433	  private readonly lastLocations = new Map<string, RubbingLocation>();
434	  /** Test-only hooks (`testHooks`): a fault injected into the next world tick, and a world tick to pause after. */
435	  private faultNext = false;
436	  private pauseAt: number | undefined;
437	  private paused = false;
438	
439	  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
440	    return authorizeEntry(options);
441	  }
442	
443	  /** The match's timings; the server's test-only setting overrides it in a subclass (`startGameServer`). */
444	  protected matchTuning(): MatchTuning {
445	    return DEFAULT_MATCH_TUNING;
446	  }
447	
448	  override async onCreate(options: unknown): Promise<void> {
449	    // Only a token-carrying request creates a match. A join by code reaches here only when its match filled up or
450	    // closed after authorizeEntry admitted it (joinOrCreate then falls back to create).
451	    const parsed = createMatchOptionsSchema.safeParse(options);
452	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, MATCH_UNAVAILABLE_MESSAGE);
453	    this.createToken = parsed.data.createToken;
454	    const code = await this.allocateCode();
455	    this.tuning = this.matchTuning();
456	    this.encounterConfig = createEncounterConfig({ map: this.config.map, rules: this.tuning.encounters });
457	    this.encounters = createEncounterState(this.encounterConfig);
458	    // One private master secret per match; each system gets its own seed derived from it, never the match code (§3, §16).
459	    this.secret = this.tuning.masterSecret();
460	    this.simulation = createMatchState(this.seedOf("world"));
461	    this.ledger = createMatchLedger({ map: this.config.map, seed: this.seedOf("ledger"), rules: this.tuning.objectives, layout: this.tuning.sourceLayout });
462	    this.finalIsland = finalIslandOf(this.config.map, this.tuning.finalSocketSecret ?? this.seedOf("final-socket"));
463	    this.flowConfig = matchConfigFor(this.tuning);
464	    this.flow = createFlowState(this.flowConfig);
465	    this.state.code = code;
466	    this.state.protocolVersion = PROTOCOL_VERSION;
467	    this.state.custom = privateMatch.custom;
468	    this.state.minPlayers = this.flowConfig.minPlayers;
469	    this.state.durationTicks = this.flowConfig.durationTicks;
470	    this.state.readyTicks = this.flowConfig.readyTicks;
471	    this.state.treasureRadius = this.tuning.claim.circleRadiusTiles * this.config.map.subUnitsPerTile;
472	    this.state.finalSector = "";
473	    this.state.finalSectorIndex = -1;
474	    this.state.endReason = "";
475	    this.state.phase = this.flow.phase;
476	    // Colyseus copied the filterBy fields of the create request, the token among them, into the listing's metadata.
477	    // Replacing the metadata drops the token before the listing is first stored.
478	    await this.setMatchmaking({ metadata: { code, custom: privateMatch.custom, started: false } });
479	
480	    this.onMessage(MessageType.Input, (client, message: unknown) => {
481	      this.gates.get(client.sessionId)?.receive(message, this.simulation.frame);
482	    });
483	    // A duel's messages reach only its machine, and only from its two fighters.
484	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveInput(client.sessionId, message));
485	    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveProbeReply(client.sessionId, message));
486	    this.onMessage(DuelMessageType.Ready, (client, message: unknown) => {
487	      if (duelReadyMessageSchema.safeParse(message).success) this.duelOfSession(client.sessionId)?.machine.markReady(client.sessionId);
488	    });
489	    this.onMessage(RubbingMessageType.ChooseTheft, (client, message: unknown) => this.receiveTheftChoice(client.sessionId, message));
490	    this.onMessage(MatchMessageType.Start, (client, message: unknown) => this.receiveStart(client.sessionId, message));
491	    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
492	    this.onMessage("*", () => undefined);
493	    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
494	  }
