625	  /** Applies a ledger step, and remembers a refusal (the room checks before it asks, so none are expected). */
626	  private ledgerStep<R extends { readonly ok: boolean; readonly rejection: string | null }>(operation: string, stepped: { state: LedgerState; result: R }): R {
627	    this.ledger = stepped.state;
628	    if (!stepped.result.ok) this.refusals.push(`${operation}: ${stepped.result.rejection}`);
629	    return stepped.result;
