632	  /**
633	   * One frame of the room's clock (60 Hz). Ships sail only while the match runs (§2: player control starts after the
634	   * ready countdown and stops at the end); before and after, every helm is neutral. On every third frame the world
635	   * tick runs in §5's order (`worldTick`), and a fault inside it aborts the match (§12).
636	   */
637	  private advance(): void {
638	    if (this.paused) return;
639	    const frame = this.simulation.frame + 1;
640	    const inputs: Record<string, PlayerInput> = {};
641	    const playing = this.inPlay();
642	    const held = this.heldPlayers();
643	    for (const [sessionId, gate] of this.gates) {
644	      // No control before the start or after the end; a reserved or respawning ship ignores its player's helm (§6).
645	      if (!playing || held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
646	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
647	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
648	    }
649	    this.simulation = step(this.config, this.simulation, inputs);
650	    for (const duel of this.seaDuels.values()) duel.machine.advance();
651	    if (!isWorldStep(this.simulation.frame)) return;
652	    const tick = this.simulation.worldTick;
653	    try {
654	      this.worldTick(frame, tick, held, playing);
655	    } catch (error) {
656	      this.fault(tick, error);
657	    }
658	    for (const gate of this.gates.values()) gate.worldStepTaken();
659	    this.checkInvariants(tick);
660	    this.mirror();
661	    if (this.pauseAt !== undefined && tick >= this.pauseAt) {
662	      this.pauseAt = undefined;
663	      this.paused = true;
664	    }
665	  }
666	
667	  /**
668	   * One world tick (20 Hz), in a fixed order. While the match runs: the ledger's clock (closed theft windows settle),
669	   * the §12 timers, then §5's order: the encounters (accepted reservations first), the ledger's holds, the claim
670	   * channel, the match flow (with this tick's claim end and accomplishments), and the reveals. Before control start
671	   * only the timers and the flow run (the lobby and the ready countdown); once the match has ended nothing changes but
672	   * the settled duels' lobbies leaving their fighters' views.
673	   */
674	  private worldTick(frame: number, tick: number, held: ReadonlySet<string>, playing: boolean): void {
675	    if (this.flow.end !== null) {
676	      this.closeShownDuels(tick);
677	      return;
678	    }
679	    if (this.faultNext) {
680	      this.faultNext = false;
681	      throw new Error("test-only fault injected into the world tick");
682	    }
683	    // The ledger's clock first: choice windows that closed settle with the default theft.
684	    this.ledgerStep("advanceLedger", advanceLedger(this.ledger, { tick }));
685	    this.runAbsences(tick);
686	    let claimEnd: FlowReport | undefined;
687	    if (playing) {
688	      this.stepEncounters(frame, held);
689	      this.stepChannels(frame, tick);
690	      claimEnd = this.stepClaim(frame, tick);
691	    }
692	    this.noteSettlements();
693	    if (playing) this.reportAccomplishments(tick);
694	    this.stepFlow(tick, claimEnd);
695	    if (this.flow.controlStartTick !== null && this.flow.end === null) this.stepReveals(tick);
696	  }
