703	  /** Players whose ship is reserved for a duel (until it is settled) or waits out of the world to respawn. */
704	  private heldPlayers(): Set<string> {
705	    const held = new Set<string>();
706	    for (const duel of this.encounters.duels) for (const id of duel.players) held.add(id);
707	    for (const player of this.encounters.players) if (player.respawn !== null) held.add(player.id);
708	    return held;
709	  }
