711	  /** The duel at sea a session fights in (until its lobby is removed). */
712	  private duelOfSession(sessionId: string): SeaDuel | undefined {
713	    for (const duel of this.seaDuels.values()) if (duel.players.includes(sessionId)) return duel;
714	    return undefined;
