723	  /**
724	   * §12 on the world tick: a fighter away from an unfinished duel for `duelAbsenceTicks` forfeits it (the duel goes on
725	   * to its settlement; they keep their seat); a disconnected player whose reservation deadline has come is removed,
726	   * their remaining rubbings going into a cache at the respawn dock the encounter rules would choose.
727	   */
728	  private runAbsences(tick: number): void {
729	    for (const [id, away] of this.away) {
730	      if (away.duelAbsentSince === undefined) continue;
731	      const duel = this.duelOfSession(id);
732	      if (duel === undefined || duel.machine.outcome !== undefined) away.duelAbsentSince = undefined;
733	      else if (tick - away.duelAbsentSince >= this.tuning.duelAbsenceTicks) {
734	        duel.machine.leave(id);
735	        away.duelAbsentSince = undefined;
736	      }
737	    }
738	    for (const player of this.ledger.players) {
739	      if (player.status !== "disconnected" || player.reservationDeadline === null || tick < player.reservationDeadline) continue;
740	      const position = this.respawnDockOf(player.id);
741	      this.ledgerStep("expireReservation", expireReservation(this.ledger, { playerId: player.id, tick, position }));
742	      // §12: an expired reservation releases the seat, which the flow counts as leaving.
743	      this.flowReports.push({ kind: "leave", playerId: player.id });
744	      const duel = this.duelOfSession(player.id);
745	      if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(player.id);
746	      const away = this.away.get(player.id);
747	      this.removePlayer(player.id);
748	      // The socket's seat goes too: Colyseus then calls onLeave, which finds the player already gone.
749	      if (typeof away?.reconnection?.reject === "function") away.reconnection.reject(false);
750	    }
751	  }
