764	  /** §12 quit: a duel in progress is forfeited (in the ledger and in the fight), the rest goes to the nearest dock. */
765	  private quit(id: string): void {
766	    const ship = this.simulation.ships.find((each) => each.id === id);
767	    const at = ship ?? dockCentre(this.config.map, 0);
768	    const position = dockCentre(this.config.map, nearestDockBySea(this.config.map, at.x, at.y));
769	    this.ledgerStep("quitPlayer", quitPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick, position }));
770	    const duel = this.duelOfSession(id);
771	    if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(id);
772	  }
