782	  /**
783	   * One world tick of §6 (`stepEncounters`): this tick's snapshot of every ship, the reports of duels that ended since
784	   * the last tick and of duels the ledger has settled, then the events applied. The rules alone choose targets, land
785	   * or miss grapples, start fights and decide returns; the room moves ships and runs the duels.
786	   */
787	  private stepEncounters(frame: number, held: ReadonlySet<string>): void {
788	    const tick = this.simulation.worldTick;
789	    const endedBy = this.protectionEndedNext;
790	    this.protectionEndedNext = new Map();
791	    const players: EncounterPlayerInput[] = this.simulation.ships.map((ship) => {
792	      const gate = this.gates.get(ship.id);
793	      const duel = this.duelOfSession(ship.id);
794	      return {
795	        id: ship.id,
796	        mode: "ship",
797	        x: ship.x,
798	        y: ship.y,
799	        heading: ship.heading,
800	        connected: this.clients.get(ship.id) !== undefined,
801	        attack: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & GRAPPLE_BUTTON) !== 0,
802	        ready: duel?.machine.isReady(ship.id) === true,
803	        // §6: last tick's collection, cache claim or treasure claim ended this player's protection.
804	        protectionEndedBy: endedBy.get(ship.id) ?? null,
805	      };
806	    });
807	    const stepped = stepEncounters(this.encounterConfig, this.encounters, { tick, players, reports: this.duelReports(tick), matchOver: false });
808	    this.encounters = stepped.state;
809	    for (const event of stepped.events) this.apply(event);
810	    this.closeShownDuels(tick);
811	  }
812	
813	  /** Settled duels whose result has been shown long enough leave their fighters' views. */
814	  private closeShownDuels(tick: number): void {
815	    for (const duel of [...this.seaDuels.values()]) if (duel.removeAfterTick !== undefined && tick > duel.removeAfterTick) this.closeSeaDuel(duel);
816	  }
817	
818	  /**
819	   * The reports for this tick. A fight that ended since the last tick is reported to the ledger (unless a player's
820	   * leaving already decided it there) and its end to the rules, as the ledger recorded it. A duel the ledger has
821	   * settled (at once for a draw, a cancellation or a win with nothing to steal; otherwise at the winner's choice or the
822	   * deadline's default) gets its `settled` report, never before: only then do its players return.
823	   */
824	  private duelReports(tick: number): DuelReport[] {
825	    const reports: DuelReport[] = [];
826	    for (const duel of this.seaDuels.values()) {
827	      const outcome = duel.machine.outcome;
828	      if (outcome !== undefined && !duel.ended) {
829	        duel.ended = true;
830	        if (findDuel(this.ledger, duel.id)?.phase === "fighting") {
831	          const winner = outcome.winner === null ? null : duel.players[outcome.winner];
832	          // §12: both fighters forfeiting on the same frame cancels; a double KO or an exact tie is a draw.
833	          const result = winner !== null ? "win" : outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw";
834	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: result, ...(winner !== null ? { winner } : {}) }));
835	        }
836	        if (!duel.endedByRules) reports.push(this.endReport(duel, tick));
837	      }
838	      if (!duel.ended || duel.settled) continue;
839	      const settled = findDuel(this.ledger, duel.id);
840	      if (settled === undefined || settled.phase === "settled") {
841	        duel.settled = true;
842	        const endTick = this.encounters.duels.find((each) => each.id === duel.id)?.end?.tick ?? tick;
843	        reports.push({ kind: "settled", duelId: duel.id, tick: Math.min(tick, Math.max(endTick, settled?.settlement?.tick ?? tick)) });
844	      }
845	    }
846	    return reports;
847	  }
848	
849	  /** The end report of a fight, as the ledger recorded its result (a quit may have decided it there first). */
850	  private endReport(duel: SeaDuel, tick: number): DuelReport {
851	    const result = findDuel(this.ledger, duel.id)?.result;
852	    if (result?.outcome === "win" && result.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: result.winner };
853	    if (result !== null && result !== undefined) return { kind: "end", duelId: duel.id, tick, outcome: result.outcome === "draw" ? "draw" : "cancelled" };
854	    const outcome = duel.machine.outcome!;
855	    if (outcome.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: duel.players[outcome.winner] };
856	    return { kind: "end", duelId: duel.id, tick, outcome: outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw" };
857	  }
858	
859	  private apply(event: EncounterEvent): void {
860	    switch (event.kind) {
861	      case "duel-reserved":
862	        this.ledgerStep("reserveDuel", reserveDuel(this.ledger, { duelId: event.duelId, players: event.players, tick: event.tick }));
863	        this.openSeaDuel(event.duelId, event.players, event.x, event.y, event.tick);
864	        return;
865	      case "duel-started":
866	        this.seaDuels.get(event.duelId)?.machine.start();
867	        return;
868	      case "duel-forfeited":
869	      case "duel-cancelled": {
870	        const duel = this.seaDuels.get(event.duelId);
871	        if (findDuel(this.ledger, event.duelId)?.phase === "fighting") {
872	          const report = event.kind === "duel-cancelled" ? { outcome: "cancelled" as const } : { outcome: "win" as const, winner: event.winner };
873	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: event.duelId, tick: event.tick, ...report }));
874	        }
875	        if (duel === undefined) return;
876	        duel.endedByRules = true;
877	        duel.ended = true;
878	        if (event.kind === "duel-cancelled") duel.machine.end(null, "cancelled");
879	        else duel.machine.end(duel.players.indexOf(event.winner) as PlayerIndex, "forfeit");
880	        return;
881	      }
882	      case "duel-settled": {
883	        const duel = this.seaDuels.get(event.duelId);
884	        if (duel === undefined) return;
885	        duel.removeAfterTick = event.tick + DUEL_RESULT_TICKS;
886	        this.state.markers.delete(duel.key);
887	        return;
888	      }
889	      case "player-returned":
890	      case "player-respawned":
891	        if (!this.simulation.ships.some((ship) => ship.id === event.playerId)) return;
892	        this.simulation = returnShip(this.config, this.simulation, event.playerId, {
893	          x: event.x,
894	          y: event.y,
895	          dock: event.kind === "player-respawned" ? (event.dockId ?? NOT_DOCKED) : NOT_DOCKED,
896	        });
897	        return;
898	      case "report-refused":
899	        this.refusedReports++;
900	        return;
901	      default:
902	        // Attempts, protection and the loser's wait are mirrored from the rules' state.
903	        return;
904	    }
905	  }
906	
907	  /** A grapple landed: both ships stop, and their duel's countdown starts, in its lobby and marker. */
908	  private openSeaDuel(id: string, players: readonly [string, string], x: number, y: number, tick: number): void {
909	    // A winner who attacks again while the last result is still showing: that lobby goes now.
910	    for (const duel of [...this.seaDuels.values()]) if (duel.players.some((player) => players.includes(player))) this.closeSeaDuel(duel);
911	    for (const player of players) if (this.simulation.ships.some((ship) => ship.id === player)) this.simulation = stopShip(this.simulation, player);
912	    const key = `d${this.nextDuelKey++}`;
913	    const lobby = new SeaDuelSchema();
914	    lobby.code = this.state.code;
915	    lobby.practice = false;
916	    this.state.duels.set(key, lobby);
917	    const machine = new DuelMachine({
918	      lobby,
919	      seed: this.seedOf(`duel:${++this.duelsOpened}`),
