1090	    const known = new Set(this.flow.players.map((player) => player.id));
1091	    const valid: FlowReport[] = [];
1092	    for (const report of reports) {
1093	      if (report.kind === "join") known.add(report.playerId);
1094	      else if (report.kind === "duel-ended" && !report.playerIds.every((id) => known.has(id))) continue;
