1380	  private noteSettlement(duel: LedgerDuel): void {
1381	    const settlement = duel.settlement!;
1382	    const result = duel.result!;
1383	    // §2's results count a settled win or draw for both fighters; a cancelled duel (both gone, or the match's end)
1384	    // counts for neither. The rubbing and gold it moved are counted from the ledger with the tick's accomplishments.
1385	    if (result.outcome !== "cancelled") this.flowReports.push({ kind: "duel-ended", playerIds: duel.players, winner: result.outcome === "win" ? result.winner : null });
1386	    for (const id of duel.players) {
1387	      const notice = this.noticesOf(id);
1388	      notice.settledAt = settlement.tick;
1389	      notice.stolen = settlement.stolenType ?? "";
1390	      notice.settledChoice = settlement.choice;
1391	      notice.choiceDeadline = duel.choiceDeadline ?? 0;
1392	      if (result.outcome !== "win") {
1393	        notice.settledRole = "draw";
1394	        notice.goldChange = 0;
1395	      } else {
1396	        const winner = result.winner === id;
1397	        notice.settledRole = winner ? "winner" : "loser";
1398	        notice.goldChange = winner ? settlement.gold : -settlement.gold;
1399	      }
1400	    }
1401	  }
