1526	    }
1527	    for (const key of [...this.state.grapples.keys()]) if (!keys.has(key)) this.state.grapples.delete(key);
1528	
1529	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
1530	    for (const id of present) {
1531	      let status = this.state.status.get(id);
1532	      if (status === undefined) {
