1551	  private mirrorObjectives(present: ReadonlySet<string>): void {
1552	    const map = this.config.map;
1553	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1554	    const held = this.heldPlayers();
1555	    for (const id of present) {
1556	      const status = this.state.status.get(id)!;
1557	      const player = findPlayer(this.ledger, id);
1558	      const ship = ships.get(id)!;
1559	      const moored = ship.dock !== NOT_DOCKED && !held.has(id) && player !== undefined;
1560	      status.gold = player?.gold ?? 0;
1561	      status.rubbings = player === undefined ? "" : heldTypes(this.ledger, id).join(",");
1562	      status.islandTypes = moored ? sealedTypesAt(this.ledger, map.docks[ship.dock]!.island).join(",") : "";
1563	      status.cacheTypes = moored ? cachedTypesAt(this.ledger, map, ship.dock).join(",") : "";
1564	      const target = moored && player.status === "connected" ? interactTarget(this.ledger, map, id, ship.dock) : undefined;
1565	      status.target = target === undefined ? "" : `${target.kind}:${target.type}`;
1566	      const channel = player?.channel ?? null;
1567	      status.channel = channel?.kind ?? "";
1568	      status.channelType = channel === null ? "" : (this.ledger.rubbings.find((rubbing) => rubbing.id === channel.rubbingId)?.type ?? "");
1569	      status.channelHeld = channel?.heldTicks ?? 0;
1570	      status.channelTotal = channel === null ? 0 : channel.kind === "collect" ? this.ledger.rules.collectTicks : this.ledger.rules.cacheClaimTicks;
1571	      const choosing = this.ledger.duels.find((duel) => duel.phase === "choosing" && duel.result?.winner === id);
1572	      const options = choosing === undefined ? [] : eligibleTheftTypes(this.ledger, choosing.id);
1573	      status.theftDuel = choosing === undefined || options.length === 0 ? "" : (this.seaDuels.get(choosing.id)?.key ?? "");
1574	      status.theftOptions = status.theftDuel === "" ? "" : options.join(",");
1575	      status.theftDeadline = status.theftDuel === "" ? 0 : choosing!.choiceDeadline!;
