1581	      status.goldChange = notice.goldChange;
1582	      status.settledAt = notice.settledAt;
1583	      status.settledChoice = notice.settledChoice;
1584	      status.choiceDeadline = notice.choiceDeadline;
1585	      this.mirrorClaim(id, status, ship, player === undefined ? false : holdsAllTypes(this.ledger, id), notice);
