1608	  private mirrorClaim(id: string, status: PlayerStatusSchema, ship: { x: number; y: number }, fullSet: boolean, notice: Notices): void {
1609	    const route = this.routes.get(id);
1610	    status.seat = this.seatOf(id);
1611	    status.fullSet = fullSet;
1612	    status.routeKnown = route !== undefined;
