1626	  /**
1627	   * Each client's view (§3, §6, §12, §16): its own ship unless it waits to respawn, the ships it can see that are not
1628	   * in a duel or waiting to respawn, the grapples whose attacker it sees or that aim at it (with the target blanked
1629	   * unless it sees the target too), the duel markers and caches in its sight, its own status and its own duel. A
1630	   * fighter or a player waiting to respawn sees no other ship, grapple, marker or cache. Nothing else is encoded for it.
1631	   */
1632	  private updateViews(): void {
1633	    const inDuel = new Set(this.encounters.duels.flatMap((duel) => duel.players));
1634	    const respawning = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
1635	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1636	    for (const client of this.clients) {
1637	      const view = client.view;
1638	      if (view === undefined) continue;
1639	      const self = client.sessionId;
1640	      const viewer = ships.get(self);
1641	      const away = inDuel.has(self) || respawning.has(self);
1642	      const sync = (item: Parameters<typeof view.add>[0], visible: boolean) => {
1643	        const shown = view.has(item);
1644	        if (visible && !shown) view.add(item);
1645	        else if (!visible && shown) view.remove(item);
1646	      };
1647	      const visible = visibleShipIds(this.config, this.simulation, self);
1648	      for (const [id, ship] of this.state.ships) {
1649	        sync(ship, id === self ? !respawning.has(id) : visible.has(id) && !away && !inDuel.has(id) && !respawning.has(id));
1650	      }
1651	      const sees = (id: string) => {
1652	        const other = ships.get(id);
1653	        return !away && viewer !== undefined && other !== undefined && canSee(this.config, viewer, other);
1654	      };
1655	      for (const attempt of this.encounters.attempts) {
1656	        const aimedAt = attempt.attackerId === self || attempt.defenderId === self;
1657	        const full = aimedAt || (sees(attempt.attackerId) && sees(attempt.defenderId));
1658	        const blank = !full && sees(attempt.attackerId);
1659	        const fullEntry = this.state.grapples.get(attempt.attackerId);
1660	        const blankEntry = this.state.grapples.get(attempt.attackerId + BLANK_GRAPPLE_SUFFIX);
1661	        if (fullEntry !== undefined) sync(fullEntry, full);
1662	        if (blankEntry !== undefined) sync(blankEntry, blank);
1663	      }
1664	      for (const marker of this.state.markers.values()) sync(marker, !away && viewer !== undefined && pointInSight(this.config, viewer, marker));
