      const line = document.createElement("tr");
      line.dataset["seat"] = String(row.seat);
      line.dataset["winner"] = String(row.winner);
      line.append(cell("td", row.label), ...row.cells.map((value) => cell("td", String(value))));
      return line;
    }),
  );
}

function headRow(): HTMLTableRowElement {
  const head = document.createElement("tr");
  for (const title of ["Player", ...RESULT_COLUMNS]) {
    const header = cell("th", title);
    header.scope = "col";
    head.append(header);
  }
  return head;
}

