''','')
s=s.replace('''import { cssColor, slotColor, type MatchView } from "./matchView.js";''','''import { cssColor, slotColor, type MatchView } from "./matchView.js";
import { treasureView, type TreasureGeometry } from "./treasureView.js";''')
