"""Branch-deletion runner: applies one mutation at a time in the scratch copy, runs its tests, records the failing ones."""
import json, os, subprocess, sys, time, importlib.util

SCRATCH = sys.argv[1]
spec = importlib.util.spec_from_file_location("muts", sys.argv[2])
muts = importlib.util.module_from_spec(spec); spec.loader.exec_module(muts)
OUT = sys.argv[3]
only = set(sys.argv[4].split(",")) if len(sys.argv) > 4 and sys.argv[4] else None
done = set()
if os.path.exists(OUT):
    for line in open(OUT):
        done.add(json.loads(line)["id"])

def vitest(project, files, pattern, report):
    cmd = ["npx", "vitest", "run", "--project", project, "--reporter=json", f"--outputFile={report}", *files]
    if pattern: cmd += ["-t", pattern]
    return cmd

def failures_vitest(report):
    try: data = json.load(open(report))
    except Exception as e: return None
    out = []
    for f in data.get("testResults", []):
        for t in f.get("assertionResults", []):
            if t["status"] == "failed": out.append(f'{os.path.relpath(f["name"], SCRATCH)} :: {t["fullName"]}')
        if f.get("status") == "failed" and not f.get("assertionResults"): out.append(f'{os.path.relpath(f["name"], SCRATCH)} :: (file failed) {f.get("message","")[:200]}')
    return out

def failures_pw(report):
    try: data = json.load(open(report))
    except Exception: return None
    out = []
    def walk(suite):
        for s in suite.get("suites", []): walk(s)
        for sp in suite.get("specs", []):
            if not sp.get("ok", True): out.append(f'{sp["file"]} :: {sp["title"]}')
    for s in data.get("suites", []): walk(s)
    return out

for m in muts.MUTATIONS:
    if m["id"] in done or (only and m["id"] not in only): continue
    path = os.path.join(SCRATCH, m["file"])
    original = open(path).read()
    count = original.count(m["old"])
    if count != 1:
        rec = {"id": m["id"], "error": f"old text occurs {count} times"}
        open(OUT, "a").write(json.dumps(rec) + "\n"); print(rec, flush=True); continue
    open(path, "w").write(original.replace(m["old"], m["new"]))
    report = os.path.join(os.path.dirname(OUT), "report.json")
    if os.path.exists(report): os.remove(report)
    kind = m["kind"]
    if kind == "e2e":
        cmd = ["npx", "--no-install", "playwright", "test", "--config=tests/e2e/playwright.config.ts", "--reporter=json", *m["files"]]
        if m.get("pattern"): cmd += ["-g", m["pattern"]]
        env = dict(os.environ, PLAYWRIGHT_JSON_OUTPUT_FILE=report)
    else:
        cmd = vitest(kind, m["files"], m.get("pattern"), report); env = dict(os.environ)
    start = time.time()
    try:
        proc = subprocess.run(cmd, cwd=SCRATCH, env=env, capture_output=True, text=True, timeout=m.get("timeout", 400))
        code = proc.returncode
    except subprocess.TimeoutExpired:
        code = "timeout"
    finally:
        open(path, "w").write(original)
    fails = failures_pw(report) if kind == "e2e" else failures_vitest(report)
    rec = {"id": m["id"], "exit": code, "seconds": round(time.time() - start), "failed": fails}
    open(OUT, "a").write(json.dumps(rec) + "\n"); print(rec, flush=True)
EOF
echo ok

